 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y, x))
            # Order the nested color bands by the area of their bounding boxes.
            ordered = sorted(colors, key=lambda color: _bbox_area(colors[color]), reverse=True)
            mapping = dict(zip(ordered, reversed(ordered)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out


def _bbox_area(cells):
    ys = [p[0] for p in cells]
    xs = [p[1] for p in cells]
    return (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1)
